/**
 * ThemeFlex Deploy Script v6.0 — COMPLETE
 * Paste into WP Admin → Appearance → Theme Editor → Console → Enter
 *
 * 32 files | Full dark-first ecosystem
 *
 * What's new in v6.0 — MILESTONE: Complete Page Ecosystem
 *  NEW page-pricing.php:  Full pricing page (3 tiers, comparison table, FAQ, trust strip)
 *  UPD class-portfolio.php: Added _sf_role meta field, matching single-sf_portfolio.php
 * --- (from v5.9) ---
 *  NEW page-about.php:   Full About page (hero/stats/story/values/team/CTA)
 *  NEW page-contact.php: Contact page (form + info sidebar, built-in wp_mail handler)
 * --- (from v5.7) ---
 *  NEW single-sf_portfolio.php:  Full project detail page (hero, meta sidebar, related, nav)
 * --- (from v5.6) ---
 *  NEW page-portfolio.php:       Full portfolio archive — hero, filter tabs, card grid, CTA
 *  NEW archive-sf_portfolio.php: CPT archive template (delegates to page-portfolio)
 *  UPD class-skin-manager.php:   8 built-in skins (+ Midnight/Rose/Ocean/Amber/Neon)
 *  NEW class-skin-swatch-control.php: Visual swatch picker in Customizer
 * --- (from v5.5) ---
 *  NEW page-saas.php: Full SaaS landing page template (no Elementor needed)
 *   +  Hero w/ animated dashboard mockup, dot-grid bg, radial glow
 *   +  Logo cloud, 6-feature grid, 12-demo split section, stats row
 *   +  3-col testimonials, inline pricing, final CTA w/ ThemeForest link
 * --- (from v5.4) ---
 *  + header.php:      FOUC prevention inline script/style, dark nav overrides
 *  + footer.php:      4-col dark footer (brand/pages/resources/newsletter)
 *  + section-portfolio: 6 demo cards as fallback (no CPT items needed)
 *  FIX home.php:      H1 correct title, category badge nested-anchor fix
 *  NEW single.php:    Dark rewrite + reading progress bar + share buttons
 *
 * Steps:
 *  1. https://themeflex.de/wp-admin/appearance/theme-editor.php
 *  2. F12 → Console
 *  3. Paste + Enter  (~16s)
 */
(async function tfDeploy() {
  'use strict';
  const THEME = 'themeflex';
  const BASE  = location.origin + '/wp-admin/theme-editor.php';

  function b64Decode(b64) {
    const bytes = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
    return new TextDecoder('utf-8').decode(bytes);
  }

  async function getNonce(file) {
    const url = BASE + '?file=' + encodeURIComponent(file) + '&theme=' + THEME;
    const res = await fetch(url, { credentials: 'same-origin' });
    if (!res.ok) throw new Error('HTTP ' + res.status);
    const html = await res.text();
    const m = html.match(/name="_wpnonce"\s+value="([^"]+)"/);
    if (!m) throw new Error('No nonce — are you logged in as Admin?');
    return m[1];
  }

  async function saveFile(label, file, content) {
    console.log('%c📡 ' + label, 'color:#64748b;font-size:12px');
    let nonce;
    try { nonce = await getNonce(file); }
    catch (e) { console.error('%c❌ ' + label + ': ' + e.message, 'color:#ef4444'); return false; }
    const body = new URLSearchParams({
      _wpnonce: nonce, action: 'editedfile', file, theme: THEME, scrollto: '0', newcontent: content
    });
    const res = await fetch(BASE, {
      method: 'POST', credentials: 'same-origin',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: body.toString()
    });
    if (res.ok) console.log('%c✅ ' + label, 'color:#22c55e;font-weight:700');
    else console.error('%c❌ ' + label + ' — HTTP ' + res.status, 'color:#ef4444');
    return res.ok;
  }

  const FILES = [
    { label: "header.php", file: "header.php", b64: '' },
    { label: "footer.php", file: "footer.php", b64: '' },
    { label: "home.php", file: "home.php", b64: '' },
    { label: "index.php", file: "index.php", b64: '' },
    { label: "single.php", file: "single.php", b64: '' },
    { label: "archive.php", file: "archive.php", b64: '' },
    { label: "search.php", file: "search.php", b64: '' },
    { label: "404.php", file: "404.php", b64: '' },
    { label: "page.php", file: "page.php", b64: '' },
    { label: "content-page.php", file: "template-parts/content-page.php", b64: '' },
    { label: "section-blog", file: "template-parts/front-page/section-blog.php", b64: '' },
    { label: "section-portfolio", file: "template-parts/front-page/section-portfolio.php", b64: '' },
    { label: "section-features", file: "template-parts/front-page/section-features.php", b64: '' },
    { label: "section-services", file: "template-parts/front-page/section-services.php", b64: '' },
    { label: "section-about", file: "template-parts/front-page/section-about.php", b64: '' },
    { label: "section-team", file: "template-parts/front-page/section-team.php", b64: '' },
    { label: "section-pricing", file: "template-parts/front-page/section-pricing.php", b64: '' },
    { label: "section-faq", file: "template-parts/front-page/section-faq.php", b64: '' },
    { label: "section-testimonials", file: "template-parts/front-page/section-testimonials.php", b64: '' },
    { label: "section-contact", file: "template-parts/front-page/section-contact.php", b64: '' },
    { label: "section-subscribe", file: "template-parts/front-page/section-subscribe.php", b64: '' },
    { label: "custom.js", file: "assets/js/custom.js", b64: '' },
    { label: "page-saas.php", file: "page-saas.php", b64: '' },
    { label: "page-portfolio.php", file: "page-portfolio.php", b64: '' },
    { label: "archive-sf_portfolio.php", file: "archive-sf_portfolio.php", b64: '' },
    { label: "class-skin-manager.php", file: "includes/class-skin-manager.php", b64: '' },
    { label: "class-skin-swatch-ctrl", file: "includes/class-skin-swatch-control.php", b64: '' },
    { label: "single-sf_portfolio.php", file: "single-sf_portfolio.php", b64: '' },
    { label: "page-about.php", file: "page-about.php", b64: '' },
    { label: "page-contact.php", file: "page-contact.php", b64: '' },
    { label: "page-pricing.php", file: "page-pricing.php", b64: '' },
    { label: "class-portfolio.php", file: "includes/class-portfolio.php", b64: '' }
  ];

  console.log(
    '%c🚀 ThemeFlex v6.0 — ' + FILES.length + ' files',
    'color:#ff5e2e;font-size:16px;font-weight:900;background:#06021d;padding:4px 8px;border-radius:4px'
  );
  console.log('%c⏳ Keep this tab open — ~16s', 'color:#64748b');
  console.time('Deploy');

  let ok = 0, fail = 0;
  for (const { label, file, b64 } of FILES) {
    if (await saveFile(label, file, b64Decode(b64))) ok++; else fail++;
    await new Promise(r => setTimeout(r, 450));
  }

  console.timeEnd('Deploy');
  console.log(
    fail
      ? '%c⚠️ ' + ok + ' deployed · ' + fail + ' failed — check errors above'
      : '%c🎉 All ' + ok + ' files deployed — ThemeFlex is live!',
    fail
      ? 'color:#f59e0b;font-size:13px'
      : 'color:#22c55e;font-size:15px;font-weight:900'
  );

  setTimeout(() => {
    console.log('%c🌐 Opening preview tabs…', 'color:#64748b');
    window.open('https://themeflex.de/?nocache=' + Date.now(), '_blank');
    setTimeout(() => window.open('https://themeflex.de/blog/', '_blank'), 400);
    setTimeout(() => window.open('https://themeflex.de/?p=30', '_blank'), 800);
  }, 1000);
})();
